11	
12	type RefsMode = "list" | "footnote" | "none";
13	
14	/** The draft blocks → a Markdown document, optionally with a source list. */
15	function draftToMarkdown(
16	  draft: ExportDraft,
17	  sources: NoteSourceRef[],
18	  refsMode: RefsMode,
19	): string {
20	  const lines: string[] = [`# ${draft.title}`, ""];
21	  for (const b of draft.blocks) {
22	    if (b.type === "h4") lines.push(`## ${b.text}`, "");
23	    else if (b.type === "note") lines.push(`> ⚠️ ${b.text}`, "");
24	    else lines.push(b.text, "");
25	  }
26	  if (refsMode !== "none" && sources.length > 0) {
27	    if (refsMode === "footnote") {
28	      lines.push("", ...sources.map((s) => `[^${s.n}]: ${s.label}`));
29	    } else {
30	      lines.push("## 出典", "", ...sources.map((s, i) => `${i + 1}. ${s.label}`));
31	    }
32	  }
33	  return `${lines.join("\n").replace(/\n{3,}/g, "\n\n").trim()}\n`;
34	}
35	
36	function slugify(title: string): string {
37	  const s = title
38	    .trim()
39	    .replace(/[\s/\\?%*:|"<>]+/g, "-")
40	    .replace(/^-+|-+$/g, "");
41	  return s || "note";
42	}
43	
44	function download(name: string, text: string) {
45	  const url = URL.createObjectURL(new Blob([text], { type: "text/markdown;charset=utf-8" }));
46	  const a = document.createElement("a");
47	  a.href = url;
48	  a.download = name;
49	  a.click();
50	  URL.revokeObjectURL(url);
51	}
