53	export function ExportClient() {
54	  const sp = useSearchParams();
55	  const [format, setFormat] = useState<ExportFormat>("blog");
56	  const [draft, setDraft] = useState<ExportDraft | null>(null);
57	  const [notes, setNotes] = useState<Note[]>([]);
58	  const [noteId, setNoteId] = useState<string>(sp.get("noteId") ?? "");
59	  const [refs, setRefs] = useState<RefsMode>("list");
60	  const [toast, setToast] = useState<string | null>(null);
61	  const [loading, setLoading] = useState(true);
62	
63	  useEffect(() => {
64	    api.notes().then((ns) => {
65	      setNotes(ns);
66	      setNoteId((cur) => cur || ns[0]?.id || "");
67	    });
68	  }, []);
69	
70	  useEffect(() => {
71	    setLoading(true);
72	    api
73	      .export(noteId, format)
74	      .then(setDraft)
75	      .catch(() => setDraft(null))
76	      .finally(() => setLoading(false));
77	  }, [format, noteId]);
78	
79	  const sources = useMemo(
80	    () => notes.find((n) => n.id === noteId)?.sources ?? [],
81	    [notes, noteId],
82	  );
83	
84	  const markdown = useMemo(
85	    () => (draft ? draftToMarkdown(draft, sources, refs) : ""),
86	    [draft, sources, refs],
87	  );
88	
89	  function flash(msg: string) {
90	    setToast(msg);
91	    setTimeout(() => setToast(null), 3200);
92	  }
93	
94	  function doDownload() {
95	    if (!draft) return;
96	    download(`${slugify(draft.title)}.md`, markdown);
97	    flash("Markdown をダウンロードしました");
98	  }
99	
100	  async function doCopy() {
101	    if (!draft) return;
102	    try {
103	      await navigator.clipboard.writeText(markdown);
104	      flash("Markdown をコピーしました");
105	    } catch {
106	      flash("コピーできませんでした（権限を確認してください）");
107	    }
108	  }
109	
110	  function run() {
111	    // "社内共有メモ" は貼り付けて使うのでクリップボードへ、それ以外はファイル書き出し。
112	    if (format === "memo") doCopy();
113	    else doDownload();
114	  }
