721	/**
722	 * "傾向を分析する" — aggregate the user's notes + saved URLs (optionally scoped
723	 * to one project) into `InsightStats`, then ask the model for the interpretive
724	 * layer. One cached row per (user, project|null), replaced on each rebuild.
725	 */
726	export async function buildInsightProfile(
727	  userId: string,
728	  projectId?: string
729	): Promise<InsightProfile> {
730	  const noteRows = await db.query.notes.findMany({
731	    where: (t, { and, eq }) =>
732	      and(eq(t.userId, userId), projectId ? eq(t.projectId, projectId) : undefined),
733	    orderBy: (t, { desc }) => [desc(t.updatedAt)],
734	  });
735	  const urlRows = await db.query.savedUrls.findMany({
736	    where: (t, { and, eq, ne }) =>
737	      and(
738	        eq(t.userId, userId),
739	        ne(t.kind, "note"),
740	        projectId ? eq(t.projectId, projectId) : undefined
741	      ),
742	    orderBy: (t, { desc }) => [desc(t.createdAt)],
743	  });
744	
745	  const notes = noteRows
746	    .map((r) => ({ title: r.title, text: deltaToPlainText(r.body).trim(), createdAt: r.createdAt }))
747	    .filter((n) => n.text.length > 0);
748	
749	  const now = Date.now();
750	  const day = 86_400_000;
751	  const noteCharTotal = notes.reduce((n, x) => n + x.text.length, 0);
752	
753	  const tagBag = [
754	    ...noteRows.flatMap((r) => (r.tags as { label: string }[]).map((t) => t.label)),
755	    ...urlRows.flatMap((r) => r.tags),
756	  ];
757	
758	  const allDates = [...noteRows.map((r) => r.createdAt), ...urlRows.map((r) => r.createdAt)].sort(
759	    (a, b) => +new Date(a) - +new Date(b)
760	  );
761	
762	  const stats: InsightStats = {
763	    noteCount: notes.length,
764	    noteCharTotal,
765	    noteCharAvg: notes.length ? Math.round(noteCharTotal / notes.length) : 0,
766	    notesLast30d: notes.filter((n) => now - +new Date(n.createdAt) < 30 * day).length,
767	    urlCount: urlRows.length,
768	    urlReadCount: urlRows.filter((r) => r.fetchStatus === "success").length,
769	    topDomains: topCounts(urlRows, (r) => r.domain, 6).map((c) => ({
770	      domain: c.value,
771	      count: c.count,
772	    })),
773	    kindMix: topCounts(urlRows, (r) => r.kind, 6).map((c) => ({
774	      kind: c.value as SourceKind,
775	      count: c.count,
776	    })),
777	    topTags: topCounts(tagBag, (t) => t.toLowerCase(), 12).map((c) => ({
778	      label: c.value,
779	      count: c.count,
780	    })),
781	    languageMix: topCounts(urlRows, (r) => r.contentLanguage, 4).map((c) => ({
782	      lang: c.value,
783	      count: c.count,
784	    })),
785	    span: allDates.length
786	      ? {
787	          firstLabel: relativeLabel(allDates[0]),
788	          lastLabel: relativeLabel(allDates[allDates.length - 1]),
789	        }
790	      : null,
791	  };
792	
793	  const read = await analyseTendencies({
794	    stats,
795	    noteExcerpts: notes.map((n) => ({ title: n.title, text: n.text })),
796	    urlBlurbs: urlRows.map((r) => ({
797	      title: r.title ?? r.domain ?? r.url,
798	      domain: r.domain ?? "",
799	      summary: r.summary ?? r.summaryLines.join(" "),
800	    })),
801	  });
802	
803	  await db
804	    .delete(schema.insightProfiles)
805	    .where(
806	      and(
807	        eq(schema.insightProfiles.userId, userId),
808	        projectId
809	          ? eq(schema.insightProfiles.projectId, projectId)
810	          : isNull(schema.insightProfiles.projectId)
811	      )
812	    );
813	  const [row] = await db
814	    .insert(schema.insightProfiles)
815	    .values({
816	      userId,
817	      projectId: projectId ?? null,
818	      stats: stats as unknown as Record<string, unknown>,
819	      profile: read.profile,
820	      themes: read.themes,
821	      leanings: read.leanings,
822	      blindSpots: read.blindSpots,
823	      nextSteps: read.nextSteps,
824	      llm: read.llm,
825	      updatedAt: new Date(),
826	    })
827	    .returning();
828	  return toInsight(row);
829	}
