14	/** Coerce a model's field to a clean string[] no matter what it actually sent. */
15	function arr(v: unknown): string[] {
16	  if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
17	  if (typeof v === "string" && v.trim()) return [v.trim()];
18	  return [];
19	}
