119	/** `llm: true` only when the model actually produced this read. */
120	export type TendencyResult = TendencyRead & { llm: boolean };
121	
122	export type TendencyInput = {
123	  stats: InsightStats;
124	  noteExcerpts: { title: string; text: string }[];
125	  urlBlurbs: { title: string; domain: string; summary: string }[];
126	};
