128	const clampWeight = (n: unknown): number => Math.min(5, Math.max(1, Math.round(Number(n) || 1)));
129	
130	/** Coerce whatever the model sent for `themes` into clean InsightTheme[]. */
131	function themeArr(v: unknown): InsightTheme[] {
132	  if (!Array.isArray(v)) return [];
133	  return v
134	    .map((t) => {
135	      const o = (t ?? {}) as Record<string, unknown>;
136	      return {
137	        label: String(o.label ?? "").trim(),
138	        weight: clampWeight(o.weight),
139	        note: String(o.note ?? "").trim(),
140	      };
141	    })
142	    .filter((t) => t.label);
143	}
