145	/** Themes/profile straight from the aggregation — used with no key or on failure. */
146	export function fallbackTendencies(stats: InsightStats): TendencyRead {
147	  const maxTag = stats.topTags[0]?.count ?? 1;
148	  const themes: InsightTheme[] = stats.topTags.slice(0, 5).map((t) => ({
149	    label: t.label,
150	    weight: clampWeight(1 + Math.round((t.count / maxTag) * 4)),
151	    note: `タグ「${t.label}」が${t.count}件`,
152	  }));
153	  const topDomain = stats.topDomains[0]?.domain;
154	  const parts = [`ノート${stats.noteCount}本・出典${stats.urlCount}本。`];
155	  if (topDomain) parts.push(`主に ${topDomain} を読み、`);
156	  if (stats.topTags[0]) parts.push(`「${stats.topTags[0].label}」への関心が目立ちます。`);
157	  return {
158	    profile: parts.join("").replace(/、$/, "。"),
159	    themes,
160	    leanings: [],
161	    blindSpots: [],
162	    nextSteps: [],
163	  };
164	}
