166	/**
167	 * Read the person's tendencies off their notes + saved URLs. The deterministic
168	 * `stats` always carry the numbers; the model adds the interpretive layer
169	 * (themes, leanings, blind spots, next steps). Falls back to `stats` alone.
170	 */
171	export async function analyseTendencies(input: TendencyInput): Promise<TendencyResult> {
172	  const { stats } = input;
173	  const thin = stats.noteCount + stats.urlCount < 3;
174	  if (!llmConfigured() || thin) return { ...fallbackTendencies(stats), llm: false };
175	
176	  try {
177	    const out = await chatJSON<TendencyRead>([
178	      {
179	        role: "system",
180	        content:
181	          "読書メモと保存URLから、その人の関心・思考の傾向を推定する。" +
182	          "断定しすぎず、必ず本人の記録に基づく根拠を添える。憶測で属性を決めつけない。" +
183	          "返答は JSON のみ: " +
184	          '{"profile":string(2〜3文の人物像),' +
185	          '"themes":[{"label":string,"weight":1..5,"note":string(根拠1行)}](3〜6),' +
186	          '"leanings":string[](2〜4, 繰り返し出る立場・論調),' +
187	          '"blindSpots":string[](2〜4, 逆に触れていない観点),' +
188	          '"nextSteps":string[](2〜3, 次に深掘りしそう／補うと良い観点)}. ' +
189	          "すべて日本語。",
190	      },
191	      {
192	        role: "user",
193	        content: JSON.stringify(
194	          {
195	            stats,
196	            notes: input.noteExcerpts.slice(0, 20).map((n) => ({
197	              title: n.title,
198	              text: n.text.slice(0, 600),
199	            })),
200	            urls: input.urlBlurbs.slice(0, 30).map((u) => ({
201	              title: u.title,
202	              domain: u.domain,
203	              summary: u.summary.slice(0, 200),
204	            })),
205	          },
206	          null,
207	          1
208	        ),
209	      },
210	    ]);
211	    const themes = themeArr(out.themes).slice(0, 6);
212	    return {
213	      profile: String(out.profile ?? "").trim() || fallbackTendencies(stats).profile,
214	      themes: themes.length ? themes : fallbackTendencies(stats).themes,
215	      leanings: arr(out.leanings).slice(0, 4),
216	      blindSpots: arr(out.blindSpots).slice(0, 4),
217	      nextSteps: arr(out.nextSteps).slice(0, 3),
218	      llm: true,
219	    };
220	  } catch (e) {
221	    if (!(e instanceof LLMError)) throw e;
