242	export async function answerSearchChat(input: {
243	  query: string;
244	  history?: ChatTurn[];
245	  candidates: { title: string; text: string }[];
246	}): Promise<SearchChatResult> {
247	  const cands = input.candidates.slice(0, 8);
248	
249	  if (!llmConfigured() || cands.length === 0) {
250	    const answer = cands.length
251	      ? `「${input.query}」に関連しそうな記録が${cands.length}件見つかりました。下の候補を確認してください。`
252	      : `「${input.query}」に一致する記録は見つかりませんでした。`;
253	    return { answer, usedIndexes: cands.map((_, i) => i + 1), llm: false };
254	  }
255	
256	  const context = cands
257	    .map((c, i) => `[${i + 1}] ${c.title}\n${c.text.slice(0, 700)}`)
258	    .join("\n\n");
259	
260	  try {
261	    const raw = await chat(
262	      [
263	        {
264	          role: "system",
265	          content:
266	            "あなたはユーザー自身のノートと保存記事だけを資料に答えるアシスタント。" +
267	            "資料にない事実は足さない。参照した資料は文末で [1] [2] のように番号で示す。" +
268	            "日本語で、3〜6文程度で簡潔に。",
269	        },
270	        ...(input.history ?? []).slice(-6),
271	        { role: "user", content: `資料:\n${context}\n\n質問: ${input.query}` },
272	      ],
273	      { temperature: 0.3, maxTokens: 700 }
274	    );
275	    const used = [...raw.matchAll(/\[(\d{1,2})\]/g)]
276	      .map((m) => Number(m[1]))
277	      .filter((n) => n >= 1 && n <= cands.length);
278	    return {
279	      answer: raw,
280	      usedIndexes: [...new Set(used)].sort((a, b) => a - b),
281	      llm: true,
282	    };
283	  } catch (e) {
284	    if (!(e instanceof LLMError)) throw e;
285	    return {
286	      answer: `AIの応答を取得できませんでした。「${input.query}」に関連する候補を下に表示します。`,
287	      usedIndexes: cands.map((_, i) => i + 1),
288	      llm: false,
