17	export function BreadcrumbProvider({ children }: { children: React.ReactNode }) {
18	  const [state, setState] = useState<BreadcrumbState>({ path: "", crumbs: [] });
19	  const setCrumbs = (path: string, crumbs: Crumb[]) => setState({ path, crumbs });
20	  return (
