25	/** A detail page (note / project / item) reports its own trailing crumb(s)
26	 *  once its data has loaded. `null` while loading — nothing is shown yet. */
27	export function useBreadcrumb(crumbs: Crumb[] | null) {
28	  const ctx = useContext(BreadcrumbContext);
29	  const pathname = usePathname();
30	  const key = crumbs ? JSON.stringify(crumbs) : "";
31	  // biome-ignore lint/correctness/useExhaustiveDependencies: `key` stands in for `crumbs` (array identity changes every render)
32	  useEffect(() => {
33	    if (!ctx || !crumbs) return;
34	    ctx.setCrumbs(pathname, crumbs);
35	  }, [ctx, pathname, key]);
36	}
