const ctx = await browser.newContext({
  storageState: "/home/nknighta/_varius/hazy-repo/apps/hazy-note/e2e/.clerk/user.json",
});
const page = await ctx.newPage();

async function shot(path, name) {
  await page.goto(`http://localhost:3000${path}`, { waitUntil: "networkidle" });
  await page.waitForTimeout(800);
  await page.screenshot({ path: `/tmp/claude-1000/-home-nknighta--varius-hazy-repo/d17ea24a-d52d-4999-8a35-348786f64357/scratchpad/${name}.png`, fullPage: true });
  console.log(name, "->", page.url());
}

await shot("/tags", "tags");
await shot("/notes", "notes");

// Grab a note id to test the note breadcrumb, then a library item id.
const noteId = await page.evaluate(async () => {
  const r = await fetch("/api/notes");
  const notes = await r.json();
  return notes[0]?.id;
});
if (noteId) await shot(`/notes/${noteId}`, "note-detail");

const itemId = await page.evaluate(async () => {
  const r = await fetch("/api/items");
  const items = await r.json();
  return items[0]?.id;
});
if (itemId) await shot(`/library/${itemId}`, "item-detail");

await shot("/library?tag=タグ0", "library-tag-filter");

