19	/** Thrown for every non-2xx response and every `{ error }` envelope. */
20	export class ApiClientError extends Error {
21	  constructor(
22	    readonly code: string,
23	    message: string,
24	    readonly status: number,
25	    readonly details?: unknown
26	  ) {
27	    super(message);
28	    this.name = "ApiClientError";
29	  }
30	}
31	
32	export interface HazyClientConfig {
33	  /** e.g. `https://api.hz.nknighta.me` (no trailing `/v1`). */
34	  baseUrl: string;
35	  /** Resolves the current Clerk session token, or null when signed out. */
36	  getToken: () => Promise<string | null>;
37	}
38	
39	type RequestInitLite = {
40	  method?: string;
41	  body?: unknown;
42	  query?: Record<string, string | number | boolean | undefined>;
43	  signal?: AbortSignal;
44	};
45	
46	type Envelope<T> =
47	  | { data: T }
48	  | { error: { code: string; message: string; details?: unknown } };
49	
50	function createRequest(config: HazyClientConfig) {
51	  return async function request<T>(path: string, init: RequestInitLite = {}): Promise<T> {
52	    const url = new URL(`/v1${path}`, config.baseUrl);
53	    for (const [key, value] of Object.entries(init.query ?? {})) {
54	      if (value !== undefined) url.searchParams.set(key, String(value));
55	    }
56	
57	    const token = await config.getToken();
58	    const res = await fetch(url, {
59	      method: init.method ?? "GET",
60	      headers: {
61	        ...(init.body !== undefined ? { "Content-Type": "application/json" } : {}),
62	        ...(token ? { Authorization: `Bearer ${token}` } : {}),
63	      },
64	      body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
65	      signal: init.signal,
66	    });
67	
68	    const json = (await res.json().catch(() => null)) as Envelope<T> | null;
69	    if (json && "error" in json) {
70	      throw new ApiClientError(json.error.code, json.error.message, res.status, json.error.details);
71	    }
72	    if (!res.ok || !json || !("data" in json)) {
73	      throw new ApiClientError("internal_error", `Request failed (${res.status})`, res.status);
74	    }
75	    return json.data;
76	  };
77	}
