36	const listQuerySchema = z.object({
37	  cursor: z.string().uuid().optional(),
38	  limit: z.coerce.number().int().min(1).max(100).default(30),
39	  sort: z.enum(["newest", "oldest"]).default("newest"),
40	});
41	
42	items.get("/", async (c) => {
43	  const user = c.get("user");
44	  const { cursor, limit, sort } = listQuerySchema.parse({
45	    cursor: c.req.query("cursor"),
46	    limit: c.req.query("limit"),
47	    sort: c.req.query("sort"),
48	  });
49	  const db = getDb();
50	
51	  let cursorCreatedAt: Date | undefined;
52	  if (cursor) {
53	    const cursorRow = await db.query.savedUrls.findFirst({ where: eq(savedUrls.id, cursor) });
54	    cursorCreatedAt = cursorRow?.createdAt;
55	  }
56	
57	  const conditions = [eq(savedUrls.userId, user.id)];
58	  if (cursorCreatedAt) {
59	    conditions.push(
60	      sort === "newest"
61	        ? lt(savedUrls.createdAt, cursorCreatedAt)
62	        : gt(savedUrls.createdAt, cursorCreatedAt)
63	    );
64	  }
65	
66	  const rows = await db.query.savedUrls.findMany({
67	    where: and(...conditions),
68	    orderBy: sort === "newest" ? [desc(savedUrls.createdAt)] : [asc(savedUrls.createdAt)],
69	    limit: limit + 1,
70	    with: { readLaterState: true },
71	  });
72	
73	  const hasMore = rows.length > limit;
74	  const page = hasMore ? rows.slice(0, limit) : rows;
75	
76	  return ok({
77	    items: page.map((row) => serializeSavedUrl(row, row.readLaterState)),
78	    nextCursor: hasMore ? page[page.length - 1].id : null,
79	  });
80	});
