121	            domain,
122	            fetchStatus: "error" as const,
123	            fetchError: result.error,
124	          }
125	    )
126	    .returning();
127	
128	  await db.insert(readLaterState).values({ userId: user.id, savedUrlId: row.id });
129	
130	  return ok(serializeSavedUrl(row), { status: 201 });
131	});
