13	
14	export function ItemTagsEditor({ item }: { item: SavedUrlDTO }) {
15	  const t = useTranslations("item");
16	  const router = useRouter();
17	  const update = useUpdateItemMutation(item.id);
18	  const [draft, setDraft] = useState("");
19	
20	  const tags = item.tags;
21	
22	  function commit(next: string[]) {
23	    update.mutate(
24	      { tags: next },
25	      {
26	        onError: (error) =>
27	          toast.error(error instanceof Error ? error.message : "Something went wrong."),
28	      }
29	    );
30	  }
31	
32	  function addTag() {
33	    const value = draft.trim().toLowerCase();
34	    setDraft("");
35	    if (!value || tags.includes(value)) return;
36	    commit([...tags, value]);
37	  }
38	
39	  function removeTag(tag: string) {
40	    commit(tags.filter((current) => current !== tag));
41	  }
42	
43	  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
44	    if (event.key === "Enter") {
45	      event.preventDefault();
46	      addTag();
47	    } else if (event.key === "Backspace" && !draft && tags.length > 0) {
48	      removeTag(tags[tags.length - 1]);
49	    }
50	  }
51	
52	  return (
53	    <div className="mb-6">
54	      <div className="mb-2 flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
55	        <Tag className="size-3" />
56	        {t("tags")}
57	        {update.isPending && <Loader2 className="size-3 animate-spin" />}
58	      </div>
59	      <div className="flex flex-wrap items-center gap-1.5">
60	        {tags.map((tag) => (
61	          <Badge key={tag} variant="secondary" className="gap-1 pr-1">
62	            <button
63	              type="button"
64	              className="max-w-[12rem] truncate hover:underline"
65	              onClick={() => router.push(`/library?q=${encodeURIComponent(`tag:${tag}`)}`)}
66	            >
67	              {tag}
68	            </button>
69	            <button
70	              type="button"
71	              aria-label={t("removeTag", { tag })}
72	              className="text-muted-foreground hover:text-foreground"
73	              onClick={() => removeTag(tag)}
74	            >
75	              <X className="size-3" />
76	            </button>
77	          </Badge>
78	        ))}
79	        <div className="flex items-center gap-1">
80	          <Input
81	            value={draft}
82	            onChange={(event) => setDraft(event.target.value)}
83	            onKeyDown={onKeyDown}
84	            onBlur={addTag}
85	            placeholder={t("addTag")}
86	            className="h-7 w-32 text-xs"
87	          />
88	          <Button
89	            type="button"
90	            variant="ghost"
91	            size="icon-sm"
92	            aria-label={t("addTag")}
93	            disabled={!draft.trim()}
94	            onClick={addTag}
95	          >
96	            <Plus className="size-3.5" />
97	          </Button>
98	        </div>
99	      </div>
100	    </div>
101	  );
102	}
