4	import { useHazyClient } from "@repo/api-client/react";
5	import type { ItemPatch, SavedUrlDTO } from "@repo/api-client";
6	
7	export function useItemQuery(id: string) {
8	  const client = useHazyClient();
9	  return useQuery({
10	    queryKey: ["item", id],
11	    queryFn: ({ signal }) => client.items.get(id, signal),
12	  });
13	}
14	
15	export function useUpdateItemMutation(id: string) {
16	  const client = useHazyClient();
17	  const queryClient = useQueryClient();
18	  return useMutation({
19	    mutationFn: (patch: ItemPatch) => client.items.update(id, patch),
20	    onSuccess: (data: SavedUrlDTO) => {
21	      queryClient.setQueryData(["item", id], data);
22	      queryClient.invalidateQueries({ queryKey: ["items"] });
23	      queryClient.invalidateQueries({ queryKey: ["search"] });
24	    },
25	  });
26	}
27	
28	export function useRefetchItemMutation(id: string) {
29	  const client = useHazyClient();
30	  const queryClient = useQueryClient();
31	  return useMutation({
32	    mutationFn: () => client.items.refetch(id),
33	    onSuccess: (data: SavedUrlDTO) => {
34	      queryClient.setQueryData(["item", id], data);
35	      queryClient.invalidateQueries({ queryKey: ["items"] });
36	    },
37	  });
38	}
39	
40	export function useSummarizeItemMutation(id: string) {
41	  const client = useHazyClient();
