import { useTranslations } from "next-intl";
import { type KeyboardEvent, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

/** Click-to-edit text — Enter/blur commits, Escape reverts. Empty commits `null`. */
export function EditableField({
  value,
  placeholder,
  onCommit,
  pending,
  label,
  className,
  inputClassName,
}: {
  value: string | null;
  placeholder: string;
  onCommit: (next: string | null) => void;
  pending?: boolean;
  label: string;
  className?: string;
  inputClassName?: string;
}) {
  const t = useTranslations("item");
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value ?? "");
  const committedRef = useRef(false);

  function start() {
    setDraft(value ?? "");
    committedRef.current = false;
    setEditing(true);
  }

  function commit() {
    if (committedRef.current) return;
    committedRef.current = true;
    setEditing(false);
    const next = draft.trim();
    if (next !== (value ?? "")) onCommit(next || null);
  }

  function revert() {
    committedRef.current = true;
    setEditing(false);
  }

  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      event.preventDefault();
      commit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      revert();
    }
  }

  if (editing) {
    return (
      // biome-ignore lint/a11y/noAutofocus: opened by an explicit user click on the edit button
      <Input
        autoFocus
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={onKeyDown}
        onBlur={commit}
        placeholder={placeholder}
        aria-label={label}
        className={cn("h-auto py-0.5", inputClassName)}
      />
    );
  }

  return (
    <span className={cn("group inline-flex min-w-0 items-center gap-1", className)}>
      <span className="min-w-0 truncate">{value || placeholder}</span>
      {pending ? (
        <Loader2 className="size-3 shrink-0 animate-spin text-muted-foreground" />
      ) : (
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={t("editField", { field: label })}
          className="shrink-0 opacity-0 group-hover:opacity-100 focus-visible:opacity-100"
          onClick={start}
        >
          <Pencil className="size-3" />
        </Button>
      )}
    </span>
  );
}

